-- READ-ONLY: changes nothing. Paste into the Supabase SQL editor and run.
-- Compares the live functions with supabase/migration-tryal-friends.sql (14 functions) by the md5 of their bodies.
--   match     the live function is exactly the file's version
--   MISMATCH  a function with that name exists but its body differs (an older or edited version is live)
--   MISSING   no function with that name
-- (Generated by scripts/gen-live-check.mjs from the file; regenerate it if the migration changes.)
with expected(fn, body_md5) as (
  values
    ('chat_check_stranger', 'e6f71df34412d19dc3c5a675b76b1957'),
    ('chat_conversation_for', '841438207b47dc89de1d48681f859008'),
    ('chat_messages_guard', '2bfbfb3fd3f89f62356f1658600af17f'),
    ('get_feed_engine', 'a24de05244f2cf576badc0a34f9923e1'),
    ('my_controls', 'cb1c373153f44c722a5a20ed05d72bb1'),
    ('my_conversations', 'f1559821688ad0ecbfba7212e85a25e6'),
    ('posts_testing_readable', '8fae69b935a8100e66b92a94f0c7ae89'),
    ('set_dm_policy', '5af18d8c47db8044d7a5b5c57f601124'),
    ('trial_fans_of', 'be983802930a11fa702240dd7cc7f92d'),
    ('trial_is_fan', '46fb5fc14eefb91511af71990d9d8bfc'),
    ('trial_is_silenced', '7f8beb5e59712b4a5d36db794050920a'),
    ('trial_is_supporter', 'a9456f2d79d234157c5f69ece9c7bcda'),
    ('trial_post_score_details', 'dcf5195737093e7b406888000aa2fb0f'),
    ('trial_supporter_creators', '702619f9040fadee93040b29fc5529fe')
)
select e.fn as function_name,
       case when not exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = e.fn) then 'MISSING'
            when exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = e.fn and md5(p.prosrc) = e.body_md5) then 'match'
            else 'MISMATCH' end as status
from expected e
order by (case when exists (select 1 from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = e.fn and md5(p.prosrc) = e.body_md5) then 1 else 0 end), e.fn;
